import base64
import sys

# Đọc toàn bộ chuỗi từ user request
b64_str = """data:image/bmp;base64,"""

raw_b64 = b64_str.split(",")[-1]
data = base64.b64decode(raw_b64)
print(f"Total BMP length: {len(data)} bytes")

# Check BMP header
header_offset = int.from_bytes(data[10:14], 'little')
w = int.from_bytes(data[18:22], 'little')
h = int.from_bytes(data[22:26], 'little')
bpp = int.from_bytes(data[28:30], 'little')
print(f"Header size: {header_offset}, Width: {w}, Height: {h}, BPP: {bpp}")

pixels = data[header_offset:]
print(f"Pixel count: {len(pixels)}")

non_zero = sum(1 for p in pixels if p != 0)
print(f"Non-zero pixels: {non_zero} / {len(pixels)} ({non_zero/len(pixels)*100:.2f}%)")

# Thống kê phân bố giá trị pixel
from collections import Counter
counts = Counter(pixels)
print(f"Top 10 pixel values: {counts.most_common(10)}")

# Thống kê từng dòng (160 dòng, mỗi dòng 160 pixels)
rows_non_zero = 0
for y in range(h):
    row = pixels[y*w : (y+1)*w]
    nz = sum(1 for p in row if p != 0)
    if nz > 0:
        rows_non_zero += 1
        print(f"Row {y}: {nz} non-zero pixels | sample: {list(row[:16])}")
print(f"Total rows with non-zero pixels: {rows_non_zero} / {h}")
